word("ungdom", {sv: "ungdom (en)", m: "ungdom(en|ar|arna)?", d: t3("Tiden när man är ung.", "The time when you are young.", "الفترة التي يكون فيها الإنسان شابًّا."), ex: "Äpplena gav gudarna deras ungdom tillbaka.", tr: {en: "youth", ar: "الشباب"}, syn: ["unga år"], opp: ["ålderdom"], wrong: ["sommar", "styrka"], gap: ["Gudarna åt ett äpple och fick tillbaka sin", "ungdom", "."], gapForm: "ungdom", form: "en ungdom – ungdomar"});
