word("fanga", {sv: "fånga", m: "fånga(r|de|t|d|des|s)?", d: t3("Ta fast någon eller något, så att det inte kommer loss.", "Catch someone or something so that it can't get away.", "أن تمسك شخصًا أو شيئًا حتى لا يستطيع الهرب."), ex: "Jätten fångade Idun och flög bort med henne.", tr: {en: "catch, capture", ar: "يمسك، يأسر"}, syn: ["ta fast"], opp: ["släppa"], wrong: ["sova", "läsa"], gap: ["Jätten ville", "fånga", "Idun och ta henne till sitt land."], gapForm: "fånga", form: "fånga – fångade – har fångat"});
