word("forvandla", {sv: "förvandla (sig)", m: "förvandla(r|de|t|ts|s|d|des)?", d: t3("Ändra något så att det blir något helt annat.", "Change something so that it becomes something completely different.", "أن تغيّر شيئًا فيصبح شيئًا آخر تمامًا."), ex: "Jätten förvandlade sig till en örn.", tr: {en: "transform, turn into", ar: "يحوّل، يتحوّل"}, syn: ["ändra"], wrong: ["gömma", "äta"], gap: ["Loke kunde", "förvandla", "sig till en falk."], gapForm: "förvandla", form: "förvandla – förvandlade – har förvandlat"});
