defineUnit({id: "sv6g", year: 6, ord: 7, title: t3("Myten om Idun och äpplena", "The myth of Idun and the apples", "أسطورة إيدون والتفاحات"), storyTitle: "Myten om Idun och äpplena",
  icon: ICON(`<path d="M0 120 L70 60 L140 110 L210 40 L320 100 V180 H0Z" fill="#a8b8c8"/>${eagle(230, 60, .7)}<rect x="40" y="120" width="110" height="42" rx="8" fill="#8d6440"/>${[60, 85, 110, 132].map(x => apple(x, 116, 12)).join("")}`, "#d9e8f5"),
  words: ["ungdom", "aldras", "gyllene", "fanga", "radda", "orn", "forvandla", "ododlig"], terms: ["svreflexiv"],
  story: [
    {text: ["Johan, läraren i 6A, satte sig på katedern med en tjock bok. ”I dag ska ni få höra en myt om gudarna i Asgård”, sa han. Yasmin och Leo lutade sig nyfiket fram.", "”Gudinnan Idun hade en ask med gyllene äpplen”, läste Johan. ”När gudarna kände sig gamla och trötta, åt de ett äpple. Då fick de tillbaka sin ungdom. De var nästan odödliga.”"],
      pic: P7[1], say: t3("Iduns äpplen är gyllene. Vad händer när gudarna äter ett äpple?", "Idun's apples are golden. What happens when the gods eat an apple?", "تفاحات إيدون ذهبية. ماذا يحدث عندما يأكل الآلهة تفاحة؟")},
    {text: ["En dag vandrade guden Loke i bergen. Plötsligt dök en stor örn ner och högg tag i honom. Det var jätten Tjatse, som hade förvandlat sig till en örn.", "Örnen flög högt upp med Loke. ”Jag lovar vad som helst!” skrek Loke. ”Ge mig Idun och hennes äpplen”, svarade jätten. Loke gav honom sitt löfte och fick komma loss."],
      pic: P7[2], say: t3("Örnen är egentligen en jätte. Vad lovar Loke för att komma loss?", "The eagle is really a giant. What does Loki promise to get free?", "النسر في الحقيقة عملاق. بماذا يعد لوكي ليتحرّر؟")},
    {text: ["Loke skyndade sig hem till Asgård. Han sa till Idun med sin listigaste röst: ”I skogen har jag hittat äpplen som är ännu finare än dina. Följ med!”", "Idun lät sig luras och följde med Loke in i skogen. Där dök örnen ner, grep tag i Idun och flög bort med henne. Nu hade jätten fångat Idun."],
      pic: P7[3], say: t3("Loke använder en list. Hur lurar han Idun?", "Loki uses a trick. How does he fool Idun?", "يستخدم لوكي حيلة. كيف يخدع إيدون؟")},
    {text: ["Utan äpplena började gudarna åldras. De fick grått hår och krokiga ryggar. Tor kunde knappt lyfta sin hammare. Gudarna samlades och frågade sig: ”Vem såg Idun sist?”", "Någon hade sett henne med Loke. Gudarna blev rasande. ”Om du inte hämtar hem Idun, får du aldrig mer komma hit!” sa de. Loke förstod att han måste rädda henne."],
      pic: P7[4], say: t3("Gudarna åldras. Vad måste Loke göra nu?", "The gods grow old. What must Loki do now?", "الآلهة يشيخون. ماذا يجب على لوكي أن يفعل الآن؟")},
    {text: ["Loke lånade gudinnan Frejas fjäderdräkt och förvandlade sig till en falk. Han flög till jättens gård. Jätten var ute och fiskade, och Idun satt ensam och grät.", "Han förvandlade Idun till en liten nöt. Sedan tog han nöten i klorna och flög iväg så fort han kunde."],
      pic: P7[5], say: t3("Loke förvandlar sig till en falk. Varför förvandlar han Idun till en nöt?", "Loki turns himself into a falcon. Why does he turn Idun into a nut?", "يحوّل لوكي نفسه إلى صقر. لماذا يحوّل إيدون إلى جوزة؟")},
    {text: ["Tjatse märkte snart att Idun var borta. Han förvandlade sig till en örn igen och flög efter dem. Örnen kom närmare och närmare.", "Gudarna såg dem komma. De lade högar av spån på muren runt Asgård. Falken susade över muren, och då tände gudarna eld. Örnen hann inte vända. Den brände sina vingar och föll ner."],
      pic: P7[6], say: t3("Örnen jagar falken. Hur stoppar gudarna örnen?", "The eagle chases the falcon. How do the gods stop the eagle?", "النسر يطارد الصقر. كيف يوقف الآلهة النسر؟")},
    {text: ["Loke förvandlade nöten till Idun igen. Hon delade ut sina gyllene äpplen, och gudarna fick tillbaka sin ungdom. De kände sig starka och glada igen.", "”Jag skulle vilja vara odödlig”, sa Yasmin när Johan slutade läsa. ”Inte jag”, sa Leo. ”Tänk om Kexi blev gammal, men inte jag.” ”Då får Kexi också ett äpple”, sa Yasmin och skrattade."],
      pic: P7[8], say: t3("Yasmin vill vara odödlig. Varför vill inte Leo det?", "Yasmin wants to be immortal. Why doesn't Leo?", "تريد ياسمين أن تكون خالدة. لماذا لا يريد ليو ذلك؟")}],
  wordsSay: t3("Nya ord från myten! Tryck på ett ord för att se vad det betyder.", "New words from the myth! Tap a word to see what it means.", "كلمات جديدة من الأسطورة! اضغط على كلمة لترى معناها."),
  grammar: [
    {draw: () => {
      const a = ["Loke", "förvandlade", "sig", "till en falk"], ca = ctr(a, 40), b = ["Gudarna", "kände", "sig", "gamla"], cb = ctr(b, 40);
      return [A.wipe(), head(t3("Reflexiva verb: sig", "Reflexive verbs: sig", "الأفعال الانعكاسية: sig")),
        A.arrow(ca[2], 136, ca[0] + 10, 136, "g", 40), ...boxes([[a[0], "b", "subjekt"], [a[1], "r", "verb"], [a[2], "g", "= Loke"], [a[3], null]], 200, 40),
        A.arrow(cb[2], 336, cb[0] + 10, 336, "g", 40), ...boxes([[b[0], "b", "subjekt"], [b[1], "r", "verb"], [b[2], "g", "= gudarna"], [b[3], null]], 400, 40)];
    }, say: t3("Loke förvandlade sig. Ordet sig pekar tillbaka på Loke själv. Det är ett reflexivt verb: den som gör något gör det mot sig själv.", "Loke förvandlade sig – Loki turned himself. The word sig points back to Loki himself. It is a reflexive verb: the one who does something does it to himself.", "Loke förvandlade sig، أي حوّل لوكي نفسه. كلمة sig تعود على لوكي نفسه. هذا فعل انعكاسي: من يقوم بالفعل يقوم به على نفسه.")},
    {draw: () => {
      const rows: [string, string, string][] = [["jag", "skyndar", "mig"], ["du", "skyndar", "dig"], ["han / hon", "skyndar", "sig"], ["vi", "skyndar", "oss"], ["ni", "skyndar", "er"], ["de", "skyndar", "sig"]];
      return [A.wipe(), head(t3("skynda sig", "hurry", "يُسرع")), ...rows.flatMap(([s, v, p], j) => [A.tx(s, 250, 128 + j * 60, 36, "b", "end"), A.tx(v, 400, 128 + j * 60, 36, "r"), A.tx(p, 530, 128 + j * 60, 38, p === "sig" ? "o" : "g", "start")]),
        A.hl(522, 220, 80, 40), A.hl(522, 400, 80, 40)];
    }, say: t3("Pronomenet följer subjektet: jag skyndar mig, du skyndar dig, vi skyndar oss, ni skyndar er. Men han, hon och de får alla sig.", "The pronoun follows the subject: jag skyndar mig, du skyndar dig, vi skyndar oss, ni skyndar er. But han, hon and de all get sig.", "الضمير يتبع الفاعل: jag skyndar mig، du skyndar dig، vi skyndar oss، ni skyndar er. أمّا han وhon وde فتأخذ كلّها sig.")},
    {draw: () => [A.wipe(), head(t3("sig eller henne?", "sig or henne?", "sig أم henne؟")),
      ...boxes([["Loke", "b"], ["förvandlade", "r"], ["sig", "g", "= Loke själv"]], 150, 38), ...boxes([["Loke", "b"], ["förvandlade", "r"], ["henne", "o", "= Idun"]], 270, 38),
      A.tx("English: He turned himself into a falcon.", 400, 370, 28, "k"), A.tx("بالعربية: تَحَوَّلَ إلى صقر", 400, 430, 34, "o"), qt(L(t3("arabiska: sig finns inne i verbet", "Arabic: sig is inside the verb", "بالعربية: معنى sig داخل الفعل نفسه")), 400, 470, 22, "o")],
    say: t3("Sig betyder alltid samma person som subjektet. Om Loke förvandlar någon annan, säger vi henne eller honom. På arabiska finns betydelsen ofta inne i verbet: تحوّل.", "Sig always means the same person as the subject. If Loki turns someone else, we say henne or honom. In Arabic the meaning is often inside the verb itself: تحوّل.", "تعني sig دائمًا الشخص نفسه الذي هو الفاعل. وإذا حوّل لوكي شخصًا آخر نقول henne أو honom. أمّا في العربية فيكون المعنى غالبًا داخل الفعل نفسه، مثل: تحوّلَ، اختبأَ.")}],
  read: [
    {q: "Vad gav Iduns äpplen gudarna?", o: ["Ungdom – de blev unga igen", "Styrka att lyfta hammaren", "Förmågan att flyga"], why: "Del 1: Då fick de tillbaka sin ungdom."},
    {q: "Vem var örnen egentligen?", o: ["Jätten Tjatse", "Guden Loke", "Gudinnan Freja"], why: "Del 2: Det var jätten Tjatse, som hade förvandlat sig till en örn."},
    {q: "Hur lurade Loke Idun?", o: ["Han sa att det fanns finare äpplen i skogen.", "Han sa att Tor var sjuk.", "Han bjöd henne på ett bröllop."], why: "Del 3: ”I skogen har jag hittat äpplen som är ännu finare än dina.”"},
    {q: "Vad hände med gudarna utan äpplena?", o: ["De började åldras.", "De blev osynliga.", "De förvandlades till fåglar."], why: "Del 4: Utan äpplena började gudarna åldras."},
    {q: "Hur tog sig Loke till jättens gård?", o: ["Han förvandlade sig till en falk.", "Han red på en häst.", "Han gick genom skogen."], why: "Del 5: Loke förvandlade sig till en falk."},
    {q: "Varför förvandlade Loke Idun till en nöt?", o: ["Så att han kunde bära henne när han flög.", "Så att jätten skulle äta upp henne.", "För att hon ville bli en nöt."], why: "En falk kan inte bära en människa, men en nöt kan den hålla i klorna."},
    {q: "Hur stoppade gudarna örnen?", o: ["De tände eld på spån på muren.", "De fångade den i ett nät.", "Tor slog den med sin hammare."], why: "Del 6: Gudarna tände eld, och örnen brände sina vingar."},
    {q: "Varför ville Leo inte vara odödlig?", o: ["Han ville inte leva längre än Kexi.", "Han var rädd för örnar.", "Han tyckte inte om äpplen."], why: "Del 7: ”Tänk om Kexi blev gammal, men inte jag.”"}],
  gram(lv, write): Problem {
    const [pre, p, post] = pick(RF), sol = svLines(tail(pre, p, post), 400, 38, "g"), hint = {say: RFH, draw: [] as Draw[]};
    if (write || lv === 2) return {kind: "text", ans: [p], show: p, q: [A.wipe(), head(t3("Skriv rätt ord: mig, dig, sig, oss eller er.", "Write the right word: mig, dig, sig, oss or er.", "اكتب الكلمة الصحيحة: mig أو dig أو sig أو oss أو er."), 80, 30), ...svLines(tail(pre, "____", post), 230, 44)], sol, hint};
    const opts = shuffle([p, ...shuffle(RFP.filter(x => x !== p)).slice(0, 2)]);
    return {kind: "choice", opts, ans: opts.indexOf(p), show: p, q: [A.wipe(), head(t3("Vilket ord passar?", "Which word fits?", "أي كلمة تناسب؟"), 80, 34), ...svLines(tail(pre, "____", post), 230, 44)], sol, hint};
  },
  help: [{say: RFH, draw: () => [A.tx("jag → mig   du → dig", 400, 170, 42, "b"), A.tx("han, hon, de → sig", 400, 260, 42, "o"), A.tx("vi → oss   ni → er", 400, 350, 42, "g")]}]});

