word("invigning", {sv: "invigning (en)", m: "invigning(en|ar|arna)?", d: t3("En fest när något nytt öppnar för första gången.", "A celebration when something new opens for the first time.", "احتفال عند افتتاح شيء جديد لأول مرة."), ex: "På fredag är det invigning av biblioteket.", tr: {en: "opening ceremony", ar: "افتتاح، حفل افتتاح"}, syn: ["öppning"], wrong: ["lektion", "rast"], gap: ["Rektorn klippte bandet på", "invigningen", "."], gapForm: "invigningen", form: "en invigning – invigningar"});
