word("budget", {sv: "budget (en)", m: "budget(en|ar)?", d: t3("En plan för hur mycket pengar man har och vad de ska räcka till.", "A plan for how much money you have and what it has to pay for.", "خطة لمقدار المال الموجود وما يجب أن يكفي له."), ex: "Skolans budget räckte inte till allt.", tr: {en: "budget", ar: "ميزانيّة"}, syn: ["kassa"], wrong: ["soffa", "rubrik"], gap: ["Skolans", "budget", "räckte inte till nya böcker."], gapForm: "budget", form: "en budget – budgetar"});
