const DS: [string, string, string][] = [["Mål!", "ropade", "Ibrahim"], ["Den var utanför", "skrek", "Noah"], ["Du fuskar alltid", "sa", "Noah"], ["Det är inte sant!", "svarade", "Ibrahim"], ["Stopp!", "sa", "Yasmin"], ["Jag kan medla", "sa", "Leo"], ["Är det mål?", "frågade", "Elsa"], ["Vi kan göra om sparken", "föreslog", "Elsa"], ["Förlåt", "mumlade", "Noah"], ["Snyggt!", "ropade", "Ibrahim"], ["Vem såg bollen?", "undrade", "Leo"], ["Det är okej", "svarade", "Ibrahim"], ["Du var en bra medlare", "sa", "Yasmin"], ["Ska vi spela igen i morgon?", "frågade", "Noah"]];
const dsRight = ([r, v, s]: [string, string, string]) => /[!?]$/.test(r) ? `”${r}” ${v} ${s}.` : `”${r}”, ${v} ${s}.`;
const dsWrong = ([r, v, s]: [string, string, string], k: number) => {
  const end = /[!?]$/.test(r);
  if (k === 0) return end ? `”${r}”, ${v} ${s}.` : `”${r},” ${v} ${s}.`;
  if (k === 1) return `”${r}${end ? "" : ","} ${v} ${s}.”`;
  return `”${r}”${end ? "" : ","} ${s} ${v}.`;
};
const DSH = t3("Repliken står inom ” ”. Sedan kommer verbet före namnet: sa Noah. Komma efter citattecknet, men inte efter ! och ?.", "The line goes inside ” ”. Then the verb comes before the name: sa Noah. A comma after the quotation mark, but not after ! and ?.", "يُكتب الكلام بين ” ”. ثم يأتي الفعل قبل الاسم: sa Noah. توضع فاصلة بعد علامة التنصيص، لكن لا توضع بعد ! و?.");

