/* [sentence with ___, kind]: m = necessary, b = good advice, fi = forbidden, f = allowed */
const MV: [string, "m" | "b" | "fi" | "f"][] = [["Kaninen ___ ha färskt vatten varje dag.", "m"], ["Du ___ lyfta kaninen i öronen.", "fi"], ["Du ___ rengöra buren varje vecka.", "b"], ["Kaniner ___ äta choklad.", "fi"], ["Du ___ ge kaninen en bit morot ibland.", "f"], ["Om kaninen är sjuk, ___ du ringa veterinären direkt.", "m"], ["Man ___ vaccinera kaninen en gång om året.", "b"], ["Kaninen ___ springa fritt i rummet en stund.", "f"], ["Du ___ lämna kaninen ensam i solen.", "fi"], ["En vuxen ___ klippa klorna om de blir för långa.", "m"], ["Du ___ sitta på golvet när du hälsar på kaninen.", "b"], ["Kexi ___ jaga kaninen.", "fi"], ["Kaninen ___ ha pinnar att gnaga på.", "m"], ["Elsas kompisar ___ klappa Smulan om de är försiktiga.", "f"], ["Man ___ byta strö oftare om det luktar.", "b"]];
const MVW: Record<string, string> = {m: "måste", b: "bör", fi: "får inte", f: "får"};
const MVC: Record<string, T3> = {m: t3("Det är nödvändigt.", "It is necessary.", "هذا ضروريّ."), b: t3("Det är ett gott råd.", "It is good advice.", "هذه نصيحة جيّدة."), fi: t3("Det är förbjudet.", "It is forbidden.", "هذا ممنوع."), f: t3("Det är tillåtet.", "It is allowed.", "هذا مسموح.")};
const MVH = t3("måste = nödvändigt, bör = ett gott råd, får = tillåtet, får inte = förbjudet.", "måste = necessary, bör = good advice, får = allowed, får inte = forbidden.", "måste = ضروريّ، bör = نصيحة جيّدة، får = مسموح، får inte = ممنوع.");

defineUnit({id: "sv6j", year: 6, ord: 10, title: t3("Instruktion: Så sköter du en kanin", "Instructions: How to look after a rabbit", "تعليمات: كيف تعتني بأرنب"), storyTitle: "Instruktion: Så sköter du en kanin",
  icon: ICON(`<rect y="130" width="320" height="50" fill="#c8a879"/>${rabbit(110, 120, 1.1)}${hay(220, 140)}<rect x="200" y="30" width="100" height="80" rx="6" fill="#fff" stroke="#9aa8c4" stroke-width="2"/><text x="250" y="60" font-family="Caveat,cursive" font-weight="700" font-size="22" text-anchor="middle" fill="#1f4fb0">1. Mat</text><text x="250" y="88" font-family="Caveat,cursive" font-weight="700" font-size="22" text-anchor="middle" fill="#1f4fb0">2. Bur</text>`, "#f5efe2"),
  words: ["kanin", "foder", "rengora", "veterinar", "vaccinera", "klor", "motionera", "tecken"], terms: ["svmodalverb"],
  story: [
    {text: ["Elsa hade fått en kanin på sin födelsedag. Den hette Smulan och var vit med en brun fläck på nosen. Johan bad Elsa och Yasmin att skriva en instruktion till klassen: Så sköter du en kanin.", "Först besökte de en veterinär och frågade om råd. Hon svarade på alla deras frågor. Sedan skrev de sin text. Här är den:"],
      pic: P10[1], say: t3("Elsa har fått en kanin. Vem frågar flickorna om råd?", "Elsa has got a rabbit. Who do the girls ask for advice?", "حصلت إلسا على أرنب. مَن تسأل الفتاتان عن النصيحة؟")},
    {text: ["1. Mat", "En kanin måste ha hö varje dag. Hö är det viktigaste fodret, och kaninen bör kunna äta när den vill. Du kan också ge lite foder från en djuraffär.", "Grönsaker och en bit morot är gott, men du får inte ge för mycket. Kaniner får inte äta choklad eller godis. Färskt vatten måste alltid finnas i buren."],
      pic: P10[2], say: t3("Vad är det viktigaste fodret? Vad får kaninen inte äta?", "What is the most important feed? What may the rabbit not eat?", "ما أهمّ علف؟ وما الذي لا يجوز للأرنب أن يأكله؟")},
    {text: ["2. Buren", "En kanin behöver mycket plats. Buren ska vara så stor att kaninen kan hoppa och stå på bakbenen. Lägg strö och hö på golvet.", "Du bör rengöra buren varje vecka. Byt strö oftare om det luktar. Kom ihåg att rengöra matskålen och vattenflaskan också."],
      pic: P10[3], say: t3("Hur ofta bör du rengöra buren?", "How often should you clean the hutch?", "كم مرة ينبغي أن تنظّف القفص؟")},
    {text: ["3. Motion, klor och tänder", "Kaniner måste få röra sig. Låt kaninen motionera ute i en hage eller inne i ett rum, några timmar varje dag.", "Kaninens klor växer hela tiden. Om kaninen springer mycket, slits de ner. Annars måste en vuxen klippa dem. Tänderna växer också, därför ska kaninen ha pinnar att gnaga på."],
      pic: P10[4], say: t3("Kaninen måste motionera. Varför behöver den pinnar att gnaga på?", "The rabbit must exercise. Why does it need sticks to chew on?", "يجب أن يتحرّك الأرنب. لماذا يحتاج إلى عيدان ليقضمها؟")},
    {text: ["4. Hälsa", "Veterinären berättade att man bör vaccinera kaninen en gång om året. Sprutan skyddar mot farliga sjukdomar. En kanin kan leva i tio år, och när den börjar åldras, bör den gå till veterinären oftare.", "Titta på kaninen varje dag. Om den inte äter, sitter stilla i ett hörn eller har blöt nos, kan det vara tecken på att den är sjuk. Då måste du ringa veterinären direkt."],
      pic: P10[5], say: t3("Vilka tecken kan visa att kaninen är sjuk?", "Which signs can show that the rabbit is ill?", "ما العلامات التي قد تدلّ على أن الأرنب مريض؟")},
    {text: ["5. Bli vänner", "En kanin är ett bytesdjur och blir lätt rädd. Du får inte lyfta den i öronen, och du får inte fånga den när den springer.", "Sätt dig på golvet och vänta tills kaninen kommer till dig. Om den blir rädd, kan du lugna den med en mjuk röst. Det tar tid, men till slut får den förtroende för dig."],
      pic: P10[6], say: t3("Hur blir man vän med en kanin?", "How do you become friends with a rabbit?", "كيف تصبح صديقًا لأرنب؟")},
    {text: ["Johan läste instruktionen högt för klassen. ”Titta på verben”, sa han. ”Måste, bör, får inte. De visar hur viktig varje regel är.”", "Efter skolan följde Yasmin med Elsa hem. Smulan satt lugnt i Elsas knä och gnagde på en morot. ”Hon har redan förtroende för dig”, sa Yasmin. Elsa log stolt."],
      pic: P10[7], say: t3("Smulan sitter i Elsas knä. Vad visar det?", "Smulan sits in Elsa's lap. What does that show?", "تجلس سمولان في حِجر إلسا. علامَ يدلّ ذلك؟")}],
  wordsSay: t3("Nya ord från instruktionen! Tryck på ett ord för att se vad det betyder.", "New words from the instructions! Tap a word to see what it means.", "كلمات جديدة من التعليمات! اضغط على كلمة لترى معناها."),
  grammar: [
    {draw: () => {
      const rows: [string, string, string][] = [["måste", "r", "nödvändigt"], ["ska", "o", "en regel, en plan"], ["bör", "o", "ett gott råd"], ["får / kan", "g", "tillåtet, möjligt"], ["får inte", "r", "förbjudet ✗"]];
      return [A.wipe(), head(t3("Hur viktigt är det?", "How important is it?", "ما مدى أهميّته؟")), A.arrow(110, 440, 110, 110, "r"), qt(L(t3("starkast", "strongest", "الأقوى")), 110, 92, 22, "r"),
        ...rows.flatMap(([w, c, m], j) => [A.tx(w, 330, 140 + j * 72, 42, c, "end"), A.tx(m, 370, 140 + j * 72, 30, "k", "start")])];
    }, say: t3("Modala hjälpverb visar hur viktig en regel är. Måste är starkast: det är nödvändigt. Bör är ett gott råd. Får betyder att det är tillåtet, och får inte betyder att det är förbjudet.", "Modal verbs show how important a rule is. Måste is strongest: it is necessary. Bör is good advice. Får means it is allowed, and får inte means it is forbidden.", "الأفعال المساعدة تبيّن مدى أهميّة القاعدة. måste هي الأقوى: الأمر ضروريّ. bör نصيحة جيّدة. får تعني أن الأمر مسموح، وfår inte تعني أنه ممنوع.")},
    {draw: () => [A.wipe(), head(t3("Hjälpverb + verb i grundform", "Modal verb + base form", "فعل مساعد + فعل في صيغة المصدر"), 60, 34),
      ...boxes([["En kanin", null], ["måste", "r", "hjälpverb"], ["ha", "b", "grundform"], ["hö", null]], 180, 42),
      ...boxes([["Du", null], ["får", "r", "hjälpverb"], ["inte", "o", "inte"], ["lyfta", "b", "grundform"], ["den", null]], 350, 42), qt(L(t3("inget att!", "no att!", "بلا att!")), 400, 460, 26, "r")],
    say: t3("Efter ett hjälpverb kommer nästa verb i grundform, utan att: måste ha, får lyfta. Ordet inte står direkt efter hjälpverbet: du får inte lyfta den.", "After a modal verb the next verb is in base form, without att: måste ha, får lyfta. The word inte comes right after the modal verb: du får inte lyfta den.", "بعد الفعل المساعد يأتي الفعل التالي في صيغة المصدر من دون att: måste ha، får lyfta. وكلمة inte تأتي مباشرة بعد الفعل المساعد: du får inte lyfta den.")},
    {draw: () => [A.wipe(), A.tx("måste inte ≠ får inte", 400, 60, 36, "b"),
      A.tx("Du får inte ge godis.", 400, 140, 38, "r"), qt("= you must not", 400, 184, 24, "r"), qt("لا يجوز أن تعطيه حلوى", 400, 216, 26, "r"),
      A.tx("Du måste inte ge morot.", 400, 290, 38, "g"), qt("= you don't have to", 400, 334, 24, "g"), qt("ليس ضروريًّا أن تعطيه جزرًا", 400, 366, 26, "g"),
      A.tx("يجب أن تنظّف القفص", 400, 428, 36, "o"), qt(L(t3("arabiska: ett ord före verbet, svenska: inget att", "Arabic: a word before the verb, Swedish: no att", "العربية: «أن» قبل الفعل، أمّا السويدية فبلا كلمة")), 400, 470, 22, "o")],
    say: t3("Se upp! Engelska must not betyder får inte. Men måste inte betyder att det inte behövs. På arabiska säger man يجب أن, men på svenska har vi inget att efter måste.", "Watch out! English must not means får inte. But måste inte means it is not needed. In Arabic you say يجب أن, but in Swedish there is no att after måste.", "انتبه! must not بالإنجليزية تعني får inte. أمّا måste inte فتعني أن الأمر ليس ضروريًّا. وفي العربية نقول «يجب أن»، أمّا في السويدية فلا نضع att بعد måste.")}],
  read: [
    {q: "Vad är det viktigaste fodret för en kanin?", o: ["Hö", "Morötter", "Godis"], why: "Del 2: Hö är det viktigaste fodret."},
    {q: "Hur ofta bör man rengöra buren?", o: ["Varje vecka", "En gång om året", "Varje timme"], why: "Del 3: Du bör rengöra buren varje vecka."},
    {q: "Varför ska kaninen ha pinnar att gnaga på?", o: ["Tänderna växer hela tiden.", "Den är alltid hungrig.", "Klorna blir för långa."], why: "Del 4: Tänderna växer också, därför ska kaninen ha pinnar att gnaga på."},
    {q: "Vad kan vara tecken på att kaninen är sjuk?", o: ["Den äter inte och sitter stilla i ett hörn.", "Den hoppar mycket.", "Den gnager på en morot."], why: "Del 5: Om den inte äter, sitter stilla i ett hörn eller har blöt nos."},
    {q: "Hur ofta bör man vaccinera kaninen?", o: ["En gång om året", "Varje vecka", "Aldrig"], why: "Del 5: en gång om året."},
    {q: "Vad får man inte göra med en kanin?", o: ["Lyfta den i öronen", "Sätta sig på golvet bredvid den", "Ge den hö"], why: "Del 6: Du får inte lyfta den i öronen."},
    {q: "Varför ska man sätta sig på golvet och vänta?", o: ["Kaninen blir lätt rädd och måste få komma själv.", "Det är skönt att sitta på golvet.", "Kaninen kan inte hoppa."], why: "Del 6: En kanin blir lätt rädd. Den får komma till dig."},
    {q: "Hur märkte Yasmin att Smulan hade förtroende för Elsa?", o: ["Smulan satt lugnt i Elsas knä och åt.", "Smulan sprang och gömde sig.", "Smulan bet Elsa i fingret."], why: "Del 7: Smulan satt lugnt i Elsas knä och gnagde på en morot."}],
  gram(lv, write): Problem {
    const [s, k] = pick(MV), a = MVW[k], sol = svLines(s.replace("___", a), 400, 36, "g"), hint = {say: MVH, draw: [] as Draw[]};
    const q = (h: T3) => [A.wipe(), head(h, 80, 32), ...svLines(s, 200, 42), qt(L(MVC[k]), 400, 330, 30, "o")];
    if (write || lv === 2) return {kind: "text", ans: k === "f" ? ["får", "kan"] : [a], show: a, q: q(t3("Skriv rätt hjälpverb: måste, bör, får eller får inte.", "Write the right modal verb: måste, bör, får or får inte.", "اكتب الفعل المساعد الصحيح: måste أو bör أو får أو får inte.")), sol, hint};
    const opts = shuffle([a, ...shuffle(Object.values(MVW).filter(x => x !== a)).slice(0, 2)]);
    return {kind: "choice", opts, ans: opts.indexOf(a), show: a, q: q(t3("Vilket hjälpverb passar?", "Which modal verb fits?", "أي فعل مساعد يناسب؟")), sol, hint};
  },
  help: [{say: MVH, draw: () => [A.tx("måste = nödvändigt", 400, 140, 40, "r"), A.tx("bör = ett gott råd", 400, 220, 40, "o"), A.tx("får = tillåtet", 400, 300, 40, "g"), A.tx("får inte = förbjudet", 400, 380, 40, "r")]}]});

