word("sagen", {sv: "sägen (en)", m: "säg(en|nen|ner|nerna)", d: t3("En gammal berättelse som folk har berättat i många år, ofta om en viss plats.", "An old story that people have told for many years, often about a certain place.", "حكاية قديمة يرويها الناس منذ سنوات طويلة، وغالبًا عن مكان معيّن."), ex: "Det finns en sägen om Näcken i tjärnen.", tr: {en: "legend", ar: "حكاية شعبيّة، أسطورة"}, syn: ["folksaga"], wrong: ["nyhet", "instruktion"], gap: ["Johan berättade en gammal", "sägen", "vid elden."], gapForm: "sägen", form: "en sägen – sägner"});
