word("tjarn", {sv: "tjärn (en)", m: "tjärn(en|ar|arna)?", d: t3("En liten, ofta mörk sjö i skogen.", "A small, often dark lake in the forest.", "بحيرة صغيرة، غالبًا داكنة، في الغابة."), ex: "Klassen grillade korv vid tjärnen.", tr: {en: "small forest lake, tarn", ar: "بحيرة صغيرة في الغابة"}, syn: ["liten sjö"], wrong: ["berg", "väg"], gap: ["Vattnet i", "tjärnen", "var mörkt och djupt."], gapForm: "tjärnen", form: "en tjärn – tjärnar"});
word("locka", {sv: "locka", m: "locka(r|de|t|s|nde|d)?", d: t3("Få någon att vilja komma eller göra något.", "Make someone want to come or do something.", "أن تجعل شخصًا يرغب في المجيء أو في فعل شيء."), ex: "Musiken lockade Olle ner till vattnet.", tr: {en: "lure, tempt", ar: "يُغري، يجذب"}, syn: ["dra till sig"], wrong: ["skrämma", "sova"], gap: ["Näcken ville", "locka", "Olle ner i vattnet."], gapForm: "locka", form: "locka – lockade – har lockat"});
word("dimmig", {sv: "dimmig", m: "dimmig(a|t|are|ast)?", d: t3("När det är dimma och man inte ser långt.", "When there is fog and you can't see far.", "عندما يكون هناك ضباب ولا ترى بعيدًا."), ex: "Det var en dimmig kväll vid tjärnen.", tr: {en: "foggy, misty", ar: "ضبابيّ"}, syn: ["disig"], opp: ["klar"], wrong: ["varm", "torr"], gap: ["Man såg inte långt den", "dimmiga", "kvällen."], gapForm: "dimmiga", form: "dimmig – dimmigt – dimmiga"});
word("hemsk", {sv: "hemsk", m: "hemsk(t|a|are|ast)?", d: t3("Mycket otäck och obehaglig.", "Very nasty and unpleasant.", "مخيف جدًّا ومزعج."), ex: "Det var hemskt att inte kunna sluta spela.", tr: {en: "terrible, horrible", ar: "فظيع، مرعب"}, syn: ["otäck", "förskräcklig"], opp: ["härlig"], wrong: ["lätt", "billig"], gap: ["Det var", "hemskt", "när Olle inte kunde sluta spela."], gapForm: "hemskt", form: "hemsk – hemskt – hemska"});
word("fly", {sv: "fly", m: "fl(y|yr|ydde|ytt|ykt)", d: t3("Springa eller ta sig bort från en fara.", "Run or get away from a danger.", "أن تهرب أو تبتعد عن خطر."), ex: "Olle kunde äntligen fly från tjärnen.", tr: {en: "flee, escape", ar: "يهرب"}, syn: ["rymma", "springa sin väg"], opp: ["stanna"], wrong: ["sjunga", "äta"], gap: ["När fiolen tystnade, kunde Olle", "fly", "hem."], gapForm: "fly", form: "fly – flydde – har flytt"});
word("svkomparativ6", {sv: "komparativ", m: "komparativ(en|er)?", d: t3("Formen som jämför två: större, bättre, äldre.", "The form that compares two: bigger, better, older.", "الصيغة التي تقارن بين اثنين: أكبر، أفضل، أكبر سنًّا."), ex: "bra – bättre", tr: {en: "comparative", ar: "صيغة المقارنة"}});
word("svsuperlativ6", {sv: "superlativ", m: "superlativ(en|er)?", d: t3("Formen som säger att något är mest av alla: störst, bäst, äldst.", "The form that says something is the most of all: biggest, best, oldest.", "الصيغة التي تقول إن الشيء هو الأكثر بين الجميع: الأكبر، الأفضل، الأكبر سنًّا."), ex: "bra – bättre – bäst", tr: {en: "superlative", ar: "صيغة التفضيل العليا"}});

