/* [sentence with ___, base form, answer, other form, made-up wrong form] */
const KP: [string, string, string, string, string][] = [["Olle spelade ___ än alla andra i byn.", "bra", "bättre", "bäst", "braare"], ["Morfar var ___ av alla i byn.", "gammal", "äldst", "äldre", "gammalast"], ["Näcken spelade ___ av alla.", "bra", "bäst", "bättre", "braast"], ["Leo är ___ än sin kusin.", "ung", "yngre", "yngst", "ungare"], ["Elsa är ___ i klassen.", "ung", "yngst", "yngre", "ungast"], ["Svarttjärn är ___ än skolans fotbollsplan.", "liten", "mindre", "minst", "litnare"], ["Den ___ fisken i tjärnen var bara en centimeter.", "liten", "minsta", "mindre", "litnaste"], ["Elden var ___ än i går.", "stor", "större", "störst", "storare"], ["Johans ryggsäck var ___ av alla.", "stor", "störst", "större", "storast"], ["Kexi är ___ än Smulan.", "gammal", "äldre", "äldst", "gammalare"], ["I år kom ___ elever än förra året.", "många", "fler", "flest", "mångare"], ["Ibrahim grillade ___ korvar av alla.", "många", "flest", "fler", "mångast"], ["Yasmin läser ___ nu än förra året.", "bra", "bättre", "bäst", "braare"], ["Vem är ___ i din familj?", "gammal", "äldst", "äldre", "gammalast"], ["Stigen hem var ___ än vi trodde.", "lång", "längre", "längst", "långare"], ["Det här är den ___ sägnen jag vet.", "bra", "bästa", "bättre", "braaste"]];
const KPH = t3("Jämför två med än: bättre än. Mest av alla: bäst. Några ord ändrar sig helt: bra – bättre – bäst, gammal – äldre – äldst.", "Compare two with än: bättre än. Most of all: bäst. Some words change completely: bra – bättre – bäst, gammal – äldre – äldst.", "للمقارنة بين اثنين نستعمل än: bättre än. والأكثر بين الجميع: bäst. وبعض الكلمات تتغيّر تمامًا: bra – bättre – bäst، gammal – äldre – äldst.");

defineUnit({id: "sv6k", year: 6, ord: 11, title: t3("Sägnen om Näcken", "The legend of Näcken", "حكاية نَكِن"), storyTitle: "Sägnen om Näcken",
  icon: ICON(`${pine(30, 80, 1, "#22402f")}${pine(290, 80, 1, "#22402f")}<rect y="110" width="320" height="70" fill="#1f3550"/><path d="M0 116 Q80 104 160 116 T320 116 V134 H0Z" fill="#fff" opacity=".45"/><ellipse cx="160" cy="132" rx="34" ry="10" fill="#5b6470"/>${fiddle(160, 80, .8, 20)}`, "#3d4f6b"),
  words: ["sagen", "fiol", "fortrollad", "tjarn", "locka", "dimmig", "hemsk", "fly"], terms: ["svkomparativ6", "svsuperlativ6"],
  story: [
    {text: ["6A hade friluftsdag vid Svarttjärn, en liten sjö mitt i skogen. Mot kvällen blev det kallt och dimmigt. Alla satt runt elden och grillade korv.", "”Vet ni att det finns en sägen om just den här tjärnen?” frågade Johan. Leo flyttade sig närmare Yasmin."],
      pic: P11[0], say: t3("Det är dimmigt vid tjärnen. Vad ska Johan berätta?", "It's foggy by the lake. What is Johan going to tell?", "الجوّ ضبابيّ عند البحيرة. ماذا سيروي يوهان؟")},
    {text: ["”För länge sedan bodde en pojke som hette Olle på en gård här i närheten”, började Johan. ”Olle spelade fiol varje kväll. Han var yngre än de andra spelmännen i byn, men redan bättre än alla. Ändå räckte det inte. Han ville bli bäst i hela landet.”", "”Hans morfar, som var den äldsta i byn, varnade honom: Gå aldrig till tjärnen när det är dimmigt. Där bor Näcken. Den som Näcken lockar ner i vattnet kan ingen rädda.”"],
      pic: P11[1], say: t3("Olle vill bli bäst. Vad varnar morfar honom för?", "Olle wants to be the best. What does his grandfather warn him about?", "يريد أولّه أن يكون الأفضل. مِمَّ يحذّره جدّه؟")},
    {text: ["”En dimmig kväll hörde Olle musik från tjärnen. Det var den vackraste musik han någonsin hade hört, mycket vackrare än hans egen. Den lockade honom ner mellan träden.”", "”Vid stranden satt en ung man på en sten i vattnet och spelade fiol. Det var Näcken.”"],
      pic: P11[2], say: t3("Musiken lockar Olle. Vem spelar vid tjärnen?", "The music lures Olle. Who is playing by the lake?", "الموسيقى تجذب أولّه. مَن يعزف عند البحيرة؟")},
    {text: ["”Jag vill spela lika bra som du”, sa Olle. Näcken log. ”Sätt dig här, så lär jag dig.” Olle satte sig på stenen bredvid honom och började spela.", "”Snart spelade Olle bättre än någonsin. Men fingrarna kunde inte sluta. Han spelade fortare och fortare. Fiolen var förtrollad, och Olle kunde inte släppa den.”"],
      pic: P11[3], say: t3("Olle spelar bättre än någonsin. Varför kan han inte sluta?", "Olle plays better than ever. Why can't he stop?", "يعزف أولّه أفضل من أيّ وقت مضى. لماذا لا يستطيع أن يتوقّف؟")},
    {text: ["”Det var hemskt. Olle var trött och rädd, men musiken bara fortsatte. Han förstod att Näcken ville locka ner honom i det djupa vattnet.”", "”Då kom han ihåg något som morfar hade sagt: Näcken tål inte när någon säger hans namn högt. Olle samlade allt sitt mod och ropade: Näcken, Näcken, jag ser dig!”"],
      pic: P11[4], say: t3("Det är hemskt för Olle. Vad kommer han ihåg?", "It's terrible for Olle. What does he remember?", "الأمر فظيع بالنسبة لأولّه. ماذا يتذكّر؟")},
    {text: ["”Näcken skrek och förvandlade sig till en vit häst. Sedan försvann han ner i tjärnen. Fiolen tystnade, och Olle kunde äntligen fly. Han sprang hem så fort han kunde.”", "”Efter den kvällen gick Olle aldrig mer till tjärnen. Men folk sa att ingen i landet spelade bättre än han. Några trodde att det var ett tecken på att han hade lärt sig något av Näcken.”"],
      pic: P11[5], say: t3("Olle kan fly. Vad sa folk om honom efteråt?", "Olle can escape. What did people say about him afterwards?", "يستطيع أولّه أن يهرب. ماذا قال الناس عنه بعد ذلك؟")},
    {text: ["Johan slutade berätta. Dimman låg tjock över tjärnen. ”Är det sant?” viskade Leo. ”Det är en sägen”, sa Johan. ”Folk har berättat den i hundratals år, och ingen vet hur den började.”", "Plötsligt hördes ett plask från vattnet. Alla hoppade till. Yasmin försökte lugna Leo: ”Det var bara en fisk.” Men Leo satt närmast elden resten av kvällen."],
      pic: P11[6], say: t3("Plask! Hur reagerar Leo och de andra?", "Splash! How do Leo and the others react?", "طرطشة! كيف يتصرّف ليو والآخرون؟")}],
  wordsSay: t3("Nya ord från sägnen! Tryck på ett ord för att se vad det betyder.", "New words from the legend! Tap a word to see what it means.", "كلمات جديدة من الحكاية! اضغط على كلمة لترى معناها."),
  grammar: [
    {draw: () => {
      const C = [170, 400, 630], rows: [string, string, string][] = [["bra", "bättre", "bäst"], ["gammal", "äldre", "äldst"], ["ung", "yngre", "yngst"], ["stor", "större", "störst"], ["liten", "mindre", "minst"], ["många", "fler", "flest"]];
      return [A.wipe(), ...["", "komparativ", "superlativ"].map((s, i) => qt(s, C[i], 56, 24, ["k", "b", "g"][i])), ...["dimmig", "dimmigare", "dimmigast"].map((s, i) => A.tx(s, C[i], 104, 26, "k")), A.p(R.line(60, 124, 740, 124, .3), "k", 2),
        A.hl(320, 140, 160, 44), A.hl(550, 140, 160, 44), ...rows.flatMap((r, j) => r.map((s, i) => A.tx(s, C[i], 172 + j * 54, 34, ["k", "b", "g"][i])))];
    }, say: t3("De flesta adjektiv får -are och -ast: dimmig, dimmigare, dimmigast. Men några vanliga ord ändrar sig mycket: bra, bättre, bäst. Gammal, äldre, äldst. De måste man lära sig utantill.", "Most adjectives get -are and -ast: dimmig, dimmigare, dimmigast. But some common words change a lot: bra, bättre, bäst. Gammal, äldre, äldst. You have to learn them by heart.", "معظم الصفات تأخذ ‎-are و‎-ast: dimmig، dimmigare، dimmigast. لكن بعض الكلمات الشائعة تتغيّر كثيرًا: bra، bättre، bäst. gammal، äldre، äldst. يجب أن نحفظها غيبًا.")},
    {draw: () => [A.wipe(), head(t3("än eller av alla", "than or of all", "من أو بين الجميع")),
      ...boxes([["Olle", null], ["spelade", null], ["bättre", "b", "komparativ"], ["än", "o", "än"], ["alla andra", null]], 180, 38),
      ...boxes([["Morfar", null], ["var", null], ["den", "g"], ["äldsta", "g", "superlativ + a"], ["i byn", null]], 340, 38),
      A.tx("Han var äldst av alla.", 400, 460, 32, "k")],
    say: t3("När vi jämför två, använder vi komparativ och än: Olle spelade bättre än alla andra. När något är mest av alla, använder vi superlativ: äldst. Efter den får superlativen -a: den äldsta.", "When we compare two, we use the comparative and än: Olle played better than all the others. When something is the most of all, we use the superlative: äldst. After den the superlative gets -a: den äldsta.", "عندما نقارن بين اثنين نستعمل صيغة المقارنة وän: عزف أولّه أفضل من الجميع. وعندما يكون الشيء الأكثر بين الجميع نستعمل صيغة التفضيل: äldst. وبعد den تأخذ صيغة التفضيل ‎-a: den äldsta.")},
    {draw: () => [A.wipe(), head(t3("Tre språk", "Three languages", "ثلاث لغات")),
      A.tx("bra – bättre – bäst", 400, 140, 40, "g"), A.tx("good – better – best", 400, 220, 38, "k"), qt(L(t3("engelska: också oregelbundet", "English: irregular too", "الإنجليزية: غير قياسيّة أيضًا")), 400, 260, 22, "k"),
      A.tx("جيّد – أفضل – الأفضل", 400, 340, 40, "o"), A.tx("كبير – أكبر – الأكبر", 400, 400, 36, "o"), qt(L(t3("arabiska: samma form för båda", "Arabic: the same form for both", "العربية: الصيغة نفسها أفعل، ومع «ال» للتفضيل")), 400, 450, 22, "o")],
    say: t3("Engelska har också oregelbundna ord: good, better, best. På arabiska används samma form för båda: أكبر من, الأكبر. Svenskan har två olika former: större och störst.", "English also has irregular words: good, better, best. In Arabic the same form is used for both: أكبر من, الأكبر. Swedish has two different forms: större and störst.", "في الإنجليزية أيضًا كلمات غير قياسيّة: good، better، best. أمّا في العربية فنستعمل الصيغة نفسها للحالتين: أكبر من، الأكبر. وفي السويدية صيغتان مختلفتان: större وstörst.")}],
  read: [
    {q: "Var satt klassen när Johan berättade sägnen?", o: ["Runt en eld vid Svarttjärn", "I klassrummet", "I biblioteket"], why: "Del 1: Alla satt runt elden vid Svarttjärn."},
    {q: "Vad ville Olle?", o: ["Bli den bästa fiolspelaren i landet", "Bli den äldsta i byn", "Flytta från byn"], why: "Del 2: Han ville bli bäst i hela landet."},
    {q: "Vad varnade morfar Olle för?", o: ["Att gå till tjärnen när det var dimmigt", "Att spela fiol på natten", "Att gå vilse i skogen"], why: "Del 2: Gå aldrig till tjärnen när det är dimmigt."},
    {q: "Varför gick Olle ner till tjärnen?", o: ["Musiken lockade honom.", "Han skulle fiska.", "Han letade efter sin morfar."], why: "Del 3: Den lockade honom ner mellan träden."},
    {q: "Varför kunde Olle inte sluta spela?", o: ["Fiolen var förtrollad.", "Han ville vinna en tävling.", "Näcken höll i hans händer."], why: "Del 4: Fiolen var förtrollad."},
    {q: "Hur kom Olle loss från Näcken?", o: ["Han ropade Näckens namn.", "Han hoppade i vattnet.", "Morfar kom och hämtade honom."], why: "Del 5: ”Näcken, Näcken, jag ser dig!”"},
    {q: "Varför var det farligt att Olle ville bli bäst?", o: ["Han lyssnade inte på varningen och följde musiken.", "Han spelade för högt för grannarna.", "Han glömde att äta."], why: "Morfar hade varnat honom, men Olle ville så gärna bli bättre att han gick ner till tjärnen ändå."},
    {q: "Varför satt Leo närmast elden resten av kvällen?", o: ["Han var rädd efter sägnen.", "Han ville sjunga.", "Han var arg på Yasmin."], why: "Leo flyttade sig redan i början närmare Yasmin, och plasket skrämde honom."}],
  gram(lv, write): Problem {
    const [s, base, a, other, bad] = pick(KP), sol = svLines(s.replace("___", a), 400, 38, "g"), hint = {say: KPH, draw: [] as Draw[]};
    const q = (h: T3) => [A.wipe(), head(h, 80, 34), ...svLines(s, 200, 42), A.tx(`(${base})`, 400, 330, 44, "o")];
    if (write || lv === 2) return {kind: "text", ans: [a], show: a, q: q(t3("Skriv ordet i rätt form.", "Write the word in the right form.", "اكتب الكلمة بالصيغة الصحيحة.")), sol, hint};
    const opts = shuffle([a, other, bad]);
    return {kind: "choice", opts, ans: opts.indexOf(a), show: a, q: q(t3("Vilken form passar?", "Which form fits?", "أي صيغة تناسب؟")), sol, hint};
  },
  help: [{say: KPH, draw: () => [A.tx("bra – bättre – bäst", 400, 170, 44, "b"), A.tx("gammal – äldre – äldst", 400, 260, 44, "g"), A.tx("liten – mindre – minst", 400, 350, 44, "o")]}]});

