/* perfect: [subject, infinitive, supine, past, made-up wrong, rest] */
const PF: [string, string, string, string, string, string][] = [["Jag", "läsa", "läst", "läste", "läsit", "fyrtio böcker i år."], ["Vi", "skriva", "skrivit", "skrev", "skrivt", "en tidning tillsammans."], ["Johan", "vara", "varit", "var", "vari", "vår lärare i tre år."], ["Klassen", "göra", "gjort", "gjorde", "görit", "stora framsteg."], ["Elsa", "få", "fått", "fick", "fåit", "en kanin."], ["Vi", "bestämma", "bestämt", "bestämde", "bestämmit", "datum för avskedsfesten."], ["Yasmin", "spela", "spelat", "spelade", "spelit", "fiol i ett år."], ["Ni", "hjälpa", "hjälpt", "hjälpte", "hjälpit", "mig mycket."], ["Jag", "vinna", "vunnit", "vann", "vinnat", "en tävling i läsning."], ["Noah", "springa", "sprungit", "sprang", "springat", "tio kilometer."], ["Vi", "äta", "ätit", "åt", "ätat", "lunch i matsalen varje dag."], ["Leo", "glömma", "glömt", "glömde", "glömmit", "sin gympapåse igen."], ["Ibrahim", "sitta", "suttit", "satt", "sittat", "i elevrådet."], ["Jag", "lära", "lärt", "lärde", "lärit", "mig mycket svenska."]];
/* subordinate clauses: [sentence with ___, answer, wrong, wrong] */
const BS: [string, string, string, string][] = [["Jag tror ___ högstadiet blir spännande.", "att", "som", "när"], ["___ jag började i fyran, var jag blyg.", "När", "Att", "Som"], ["Johan är en lärare ___ alltid lyssnar.", "som", "att", "när"], ["Jag var nervös ___ jag inte kände någon.", "eftersom", "som", "att"], ["Elsa har en kanin ___ heter Smulan.", "som", "att", "när"], ["Jag kommer att sakna Johan ___ vi slutar.", "när", "som", "att"], ["Jag hoppas ___ vi får bra lärare.", "att", "som", "när"], ["Vi har läst en sägen ___ handlar om Näcken.", "som", "att", "när"], ["Leo var trött ___ han hade sprungit hela vägen.", "eftersom", "som", "att"], ["Johan sa ___ vi har gjort stora framsteg.", "att", "som", "när"], ["___ vi kom tillbaka efter sommaren, var biblioteket stängt.", "När", "Som", "Att"]];
const PFH = t3("Perfekt: har + supinum. läsa → har läst, skriva → har skrivit.", "Perfect: har + supine. läsa → har läst, skriva → har skrivit.", "الماضي التامّ: har + صيغة supinum. läsa ← har läst، skriva ← har skrivit.");
const BSH = t3("att efter tro, hoppas och säga. när om tid. som om en person eller sak. eftersom om en orsak.", "att after tro, hoppas and säga. när for time. som about a person or thing. eftersom for a reason.", "att بعد tro وhoppas وsäga. när للزمن. som لشخص أو شيء. eftersom للسبب.");

defineUnit({id: "sv6l", year: 6, ord: 12, title: t3("Brevet till sjuan", "The letter to year 7", "الرسالة إلى الصف السابع"), storyTitle: "Brevet till sjuan",
  icon: ICON(`<rect x="90" y="30" width="140" height="120" fill="#fff" stroke="#9aa8c4" stroke-width="3"/><path d="M90 30 l70 54 l70 -54" stroke="#9aa8c4" stroke-width="3" fill="none"/><text x="160" y="134" font-family="Caveat,cursive" font-weight="700" font-size="30" text-anchor="middle" fill="#1f4fb0">Hej sjuan!</text><rect x="196" y="40" width="24" height="28" fill="#e0b43a"/>`, "#fff6e0"),
  words: ["mellanstadiet", "hogstadiet", "avsluta", "forvantning", "framsteg", "spannande", "avskedsfest", "saknad"], terms: ["svperfekt", "svhuvudsats"],
  story: [
    {text: ["Det var de sista veckorna på mellanstadiet. Johan delade ut papper och pennor. ”I dag ska ni skriva ett brev till er nya klass i sjuan”, sa han. ”Breven läses upp den första dagen efter sommarlovet.”", "Yasmin tittade ut genom fönstret. Hon tänkte på allt som hade hänt sedan hon började i fyran. Sedan började hon skriva."],
      pic: P12[0], say: t3("Yasmin ska skriva ett brev. Vem ska läsa det?", "Yasmin is going to write a letter. Who will read it?", "ستكتب ياسمين رسالة. مَن سيقرؤها؟")},
    {text: ["Hej sjuan!", "Jag heter Yasmin och är tolv år. Nu ska jag snart avsluta mellanstadiet på Björkskolan, och i höst börjar jag på högstadiet. Min storebror Amir går redan där.", "När jag började i fyran, var jag blyg och kunde inte så mycket svenska. Men jag hade tur, eftersom jag fick en kompis direkt. Han heter Leo och har en hund som heter Kexi."],
      pic: P12[1], say: t3("Yasmin berättar om sig själv. Hur var hon när hon började i fyran?", "Yasmin tells about herself. What was she like when she started year 4?", "تتحدّث ياسمين عن نفسها. كيف كانت عندما بدأت الصفّ الرابع؟")},
    {text: ["Sedan dess har jag gjort stora framsteg. Jag har läst fler böcker än jag kan räkna, och jag har lärt mig skriva både nyheter, instruktioner och brev. I år har vi läst myter och sägner som jag aldrig hade hört förut.", "Det bästa minnet är kanske invigningen av vårt nya bibliotek. Leo och jag skrev en artikel om den i skoltidningen."],
      pic: P12[2], say: t3("Yasmin har gjort framsteg. Vilket är hennes bästa minne?", "Yasmin has made progress. What is her best memory?", "حقّقت ياسمين تقدّمًا. ما أجمل ذكرى لديها؟")},
    {text: ["Allt har inte varit lätt. Vi har bråkat ibland, som alla klasser gör. En gång blev det ett stort bråk på rasten. Men vi har lärt oss att lyssna på varandra och att medla. Nu har vi förtroende för varandra.", "Och tack vare elevrådet har vi fått riktiga fotbollsmål med nät på skolgården."],
      pic: P12[3], say: t3("Klassen har bråkat ibland. Vad har de lärt sig?", "The class has argued sometimes. What have they learned?", "تشاجر الصفّ أحيانًا. ماذا تعلّموا؟")},
    {text: ["Jag har många förväntningar på högstadiet. Jag tror att det blir spännande med nya ämnen, nya lärare och ett eget skåp i korridoren.", "Men jag är också lite nervös, eftersom allt blir nytt igen. Därför hoppas jag att någon av er visar oss runt den första dagen."],
      pic: P12[4], say: t3("Yasmin har förväntningar men är också nervös. Varför?", "Yasmin has expectations but is also nervous. Why?", "لدى ياسمين توقّعات لكنها متوتّرة أيضًا. لماذا؟")},
    {text: ["Om några veckor har vi avskedsfest i matsalen. Vi ska äta tårta, och Johan har lovat att spela gitarr. Elsa tar med sin kanin, om hon får. Jag tror att det blir både roligt och lite sorgligt.", "Jag vet att jag kommer att känna saknad efter Johan, som har varit vår lärare i tre år. Han har inspirerat oss att läsa och att tro på oss själva."],
      pic: P12[5], say: t3("Det blir avskedsfest. Varför blir den lite sorglig?", "There will be a farewell party. Why will it be a little sad?", "ستكون هناك حفلة وداع. لماذا ستكون حزينة قليلًا؟")},
    {text: ["Vi ses i augusti! Hälsningar, Yasmin", "Yasmin vek ihop brevet och lade det i ett kuvert. Leo tittade på henne. ”Vad skrev du?” ”Det får du höra i höst”, sa Yasmin och log. Ute på skolgården skällde Kexi, som alltid väntade på Leo efter skolan."],
      pic: P12[6], say: t3("Brevet är klart. Varför vill Yasmin inte berätta för Leo vad hon skrev?", "The letter is ready. Why doesn't Yasmin want to tell Leo what she wrote?", "الرسالة جاهزة. لماذا لا تريد ياسمين أن تخبر ليو بما كتبت؟")}],
  wordsSay: t3("Nya ord från brevet! Tryck på ett ord för att se vad det betyder.", "New words from the letter! Tap a word to see what it means.", "كلمات جديدة من الرسالة! اضغط على كلمة لترى معناها."),
  grammar: [
    {draw: () => {
      const rows: [string, string][] = [["läsa", "har läst"], ["skriva", "har skrivit"], ["göra", "har gjort"], ["vara", "har varit"], ["lära sig", "har lärt sig"]];
      return [A.wipe(), head(t3("Perfekt: har + supinum", "Perfect: har + supine", "الماضي التامّ: har + supinum")), ...boxes([["Jag", null], ["har", "r", "har"], ["gjort", "b", "supinum"], ["stora framsteg", null]], 160, 40),
        ...rows.flatMap(([a, b], j) => [A.tx(a, 300, 260 + j * 48, 32, "k", "end"), A.arrow(320, 250 + j * 48, 400, 250 + j * 48, "k"), A.tx(b, 420, 260 + j * 48, 32, "b", "start")])];
    }, say: t3("Perfekt berättar om något som har hänt och som är viktigt nu: Jag har gjort stora framsteg. Det byggs med har och supinum.", "The perfect tells about something that has happened and matters now: I have made great progress. It is built with har and the supine.", "الماضي التامّ يخبر عن شيء حدث وما زال مهمًّا الآن: لقد حقّقتُ تقدّمًا كبيرًا. ويُبنى بـ har وصيغة supinum.")},
    {draw: () => [A.wipe(), head(t3("Huvudsats + bisats", "Main clause + subordinate clause", "جملة رئيسية + جملة فرعية"), 60, 34),
      ...boxes([["Jag tror", "b", "huvudsats"], ["att", "o"], ["det blir spännande.", "g", "bisats"]], 160, 34),
      ...boxes([["Jag var nervös", "b", "huvudsats"], ["eftersom", "o"], ["allt blir nytt.", "g", "bisats"]], 280, 34),
      ...boxes([["Johan,", "b"], ["som", "o"], ["har varit vår lärare,", "g", "bisats"]], 400, 34)],
    say: t3("En bisats kan inte stå ensam. Den börjar ofta med att, när, som eller eftersom: Jag tror att det blir spännande. Jag var nervös eftersom allt blir nytt.", "A subordinate clause cannot stand alone. It often begins with att, när, som or eftersom: I think that it will be exciting. I was nervous because everything will be new.", "الجملة الفرعية لا تستطيع أن تقف وحدها. وغالبًا تبدأ بـ att أو när أو som أو eftersom: أظنّ أن الأمر سيكون مشوّقًا. كنت متوتّرة لأن كلّ شيء سيصبح جديدًا.")},
    {draw: () => [A.wipe(), head(t3("inte i bisatsen", "inte in the subordinate clause", "inte في الجملة الفرعية")),
      ...boxes([["Jag", null], ["har", "r"], ["inte", "o"], ["varit nervös.", null]], 170, 40), qt(L(t3("huvudsats: inte efter verbet", "main clause: inte after the verb", "الجملة الرئيسية: inte بعد الفعل")), 400, 230, 24, "k"),
      ...boxes([["… eftersom jag", null], ["inte", "o"], ["har", "r"], ["varit där.", null]], 330, 40), qt(L(t3("bisats: inte före verbet", "subordinate clause: inte before the verb", "الجملة الفرعية: inte قبل الفعل")), 400, 390, 24, "k"),
      A.tx("I have read.", 260, 460, 30, "k"), A.tx("لقد قرأتُ", 560, 460, 32, "o")],
    say: t3("I en huvudsats står inte efter verbet: Jag har inte varit nervös. I en bisats står inte före verbet: eftersom jag inte har varit där. Engelska säger I have read, som svenskan. Arabiska använder oftast bara dåtid: لقد قرأتُ.", "In a main clause inte comes after the verb: Jag har inte varit nervös. In a subordinate clause inte comes before the verb: eftersom jag inte har varit där. English says I have read, like Swedish. Arabic usually just uses the past: لقد قرأتُ.", "في الجملة الرئيسية تأتي inte بعد الفعل: Jag har inte varit nervös. وفي الجملة الفرعية تأتي inte قبل الفعل: eftersom jag inte har varit där. الإنجليزية تقول I have read مثل السويدية، أمّا العربية فتستعمل غالبًا الماضي: لقد قرأتُ.")}],
  read: [
    {q: "Vem ska läsa Yasmins brev?", o: ["Hennes nya klass i sjuan", "Hennes farmor", "Rektorn"], why: "Del 1: ett brev till er nya klass i sjuan."},
    {q: "Hur var Yasmin när hon började i fyran?", o: ["Blyg, och hon kunde inte så mycket svenska", "Arg och busig", "Bäst i klassen på svenska"], why: "Del 2: När jag började i fyran, var jag blyg."},
    {q: "Vilket minne är kanske Yasmins bästa?", o: ["Invigningen av det nya biblioteket", "Bråket på rasten", "Kvällen vid tjärnen"], why: "Del 3: Det bästa minnet är kanske invigningen av vårt nya bibliotek."},
    {q: "Vad har klassen lärt sig efter bråken?", o: ["Att lyssna på varandra och medla", "Att aldrig spela fotboll", "Att alltid fråga rektorn"], why: "Del 4: vi har lärt oss att lyssna på varandra och att medla."},
    {q: "Varför är Yasmin lite nervös för högstadiet?", o: ["Allt blir nytt igen.", "Hon har inga kompisar.", "Hon tycker inte om att läsa."], why: "Del 5: eftersom allt blir nytt igen."},
    {q: "Vad ska hända på avskedsfesten?", o: ["De ska äta tårta, och Johan ska spela gitarr.", "De ska åka på utflykt.", "De ska skriva prov."], why: "Del 6: Vi ska äta tårta, och Johan har lovat att spela gitarr."},
    {q: "Varför tror Yasmin att festen blir lite sorglig?", o: ["Klassen ska sluta hos Johan och skiljas.", "Det blir ingen tårta.", "Elsa får inte ta med kaninen."], why: "Det är en avskedsfest, och hon kommer att sakna Johan."},
    {q: "Varför vill Yasmin inte berätta för Leo vad hon skrev?", o: ["Hon vill att han ska höra det när brevet läses upp i höst.", "Hon har inte skrivit något.", "Hon är arg på Leo."], why: "Del 7: ”Det får du höra i höst.” Breven läses upp efter sommarlovet."}],
  gram(lv, write): Problem {
    if (!write && lv < 2 && Math.random() < .5) {
      const [s, a, w1, w2] = pick(BS), opts = shuffle([a, w1, w2]);
      return {kind: "choice", opts, ans: opts.indexOf(a), show: a, q: [A.wipe(), head(t3("Vilket ord börjar bisatsen?", "Which word begins the subordinate clause?", "أي كلمة تبدأ الجملة الفرعية؟"), 80, 34), ...svLines(s, 230, 42)],
        sol: svLines(s.replace("___", a), 400, 36, "g"), hint: {say: BSH, draw: []}};
    }
    const [subj, inf, sup, past, bad, rest] = pick(PF), a = `har ${sup}`, sol = svLines(`${subj} ${a} ${rest}`, 400, 38, "g"), hint = {say: PFH, draw: [] as Draw[]};
    const q = (h: T3) => [A.wipe(), head(h, 80, 32), ...svLines(`${subj} ____ ${rest}`, 210, 44), A.tx(`(${inf})`, 400, 340, 44, "o")];
    if (write || lv === 2) return {kind: "text", ans: [a], show: a, q: q(t3("Skriv verbet i perfekt: har + supinum.", "Write the verb in the perfect: har + supine.", "اكتب الفعل في الماضي التامّ: har + supinum.")), sol, hint};
    const opts = shuffle([a, `har ${past}`, `har ${bad}`]);
    return {kind: "choice", opts, ans: opts.indexOf(a), show: a, q: q(t3("Vilken form är rätt?", "Which form is right?", "أي صيغة صحيحة؟")), sol, hint};
  },
  help: [{say: PFH, draw: () => [A.tx("läsa → har läst", 400, 170, 44, "b"), A.tx("göra → har gjort", 400, 260, 44, "b"), A.tx("att · när · som · eftersom", 400, 360, 40, "o")]}]});
